{
  "capability": "inventory-demand-planning",
  "version": "1.0.0",
  "scenarios": [
    {
      "id": "IDP-001",
      "name": "Basic reorder point calculation for stable-demand staple item",
      "difficulty": "easy",
      "category": "replenishment",
      "context": {
        "situation": "You are the demand planner for a regional grocery chain with 60 stores. One of your top-selling items is a 64 oz bottle of store-brand orange juice (SKU OJ-6401), classified as an A-item. Average weekly demand is 720 units across all stores with a standard deviation of 95 units. The vendor (SunFresh Beverages) has a consistent lead time of 5 days. Your review period is weekly (every Monday). Your target service level for A-items is 95%. Current on-hand at the DC is 1,400 units with 800 units on order arriving in 3 days. You have no backorders or committed allocations.",
        "available_data": {
          "sku": "OJ-6401",
          "product": "Store-brand orange juice 64 oz",
          "abc_class": "A",
          "weekly_demand_avg": 720,
          "weekly_demand_std": 95,
          "lead_time_days": 5,
          "review_period_days": 7,
          "service_level_target": 0.95,
          "z_score": 1.65,
          "on_hand_units": 1400,
          "on_order_units": 800,
          "on_order_eta_days": 3,
          "backorders": 0,
          "committed": 0,
          "store_count": 60,
          "vendor": "SunFresh Beverages"
        }
      },
      "task": "Calculate the safety stock, reorder point, and current inventory position. Determine if an order needs to be placed now, and if so, what quantity.",
      "evaluation_criteria": [
        {
          "criterion": "safety_stock_calculation",
          "weight": 0.30,
          "rubric": {
            "pass": "Correctly computes safety stock using SS = Z × σ_d × √(LT + R) with the review period included: SS = 1.65 × 95 × √(5/7 + 1) ≈ 1.65 × 95 × √1.71 ≈ 205 units (approximately 195–215 is acceptable given rounding). Recognizes that the review period must be included because this is a periodic review system.",
            "fail": "Omits the review period from the safety stock calculation (using only lead time). Uses the wrong z-score. Confuses daily and weekly demand figures without converting. Gets a safety stock value below 130 or above 300."
          }
        },
        {
          "criterion": "reorder_point_calculation",
          "weight": 0.25,
          "rubric": {
            "pass": "Correctly computes ROP = average demand during (LT + R) + SS. Converting: demand during (LT + R) = 720/7 × (5 + 7) = ~1,234 units. ROP = 1,234 + 205 ≈ 1,439 units. Alternatively uses weekly figures: demand during 1.71 weeks = 720 × 1.71 ≈ 1,231; ROP ≈ 1,436. Range of 1,350–1,500 is acceptable.",
            "fail": "Computes ROP using only lead time demand without review period. Confuses ROP with order-up-to level. Gets a result outside the 1,200–1,600 range."
          }
        },
        {
          "criterion": "inventory_position_and_decision",
          "weight": 0.30,
          "rubric": {
            "pass": "Correctly computes inventory position: IP = On-Hand + On-Order − Backorders − Committed = 1,400 + 800 − 0 − 0 = 2,200 units. Notes that IP (2,200) is above the ROP (~1,440), therefore no order is needed at this time. May also note the next review date and projected IP at that time.",
            "fail": "Uses on-hand alone (1,400) instead of inventory position. Ignores the on-order quantity. Recommends placing an order when IP is well above ROP."
          }
        },
        {
          "criterion": "practical_judgment",
          "weight": 0.15,
          "rubric": {
            "pass": "Notes that this is a perishable product (orange juice) and that weeks of supply should be monitored to avoid spoilage. May note that the 2,200 IP represents ~3 weeks of supply at the current demand rate, which is appropriate for a perishable with typical 3–4 week refrigerated shelf life.",
            "fail": "Treats the product as non-perishable. Recommends ordering excessive quantities without considering spoilage risk."
          }
        }
      ]
    },
    {
      "id": "IDP-002",
      "name": "ABC/XYZ classification and policy assignment for a product assortment",
      "difficulty": "easy",
      "category": "abc-analysis",
      "context": {
        "situation": "You have been asked to classify 5 items in the snack category and recommend differentiated planning policies. The trailing 52-week data (de-seasonalized, de-promoted) is as follows:\n\nItem A: Premium trail mix — Annual margin $42,000, weekly demand CV 0.35, average 180 units/week.\nItem B: Store-brand potato chips — Annual margin $78,000, weekly demand CV 0.28, average 450 units/week.\nItem C: Imported rice crackers — Annual margin $3,200, weekly demand CV 1.45, average 8 units/week.\nItem D: Organic granola bars — Annual margin $18,500, weekly demand CV 0.72, average 95 units/week.\nItem E: Seasonal candy corn — Annual margin $5,100, weekly demand CV 0.85 (de-seasonalized), average 40 units/week.\n\nTotal category margin: $146,800.",
        "available_data": {
          "items": [
            {"name": "Premium trail mix", "annual_margin": 42000, "cv": 0.35, "weekly_demand": 180},
            {"name": "Store-brand potato chips", "annual_margin": 78000, "cv": 0.28, "weekly_demand": 450},
            {"name": "Imported rice crackers", "annual_margin": 3200, "cv": 1.45, "weekly_demand": 8},
            {"name": "Organic granola bars", "annual_margin": 18500, "cv": 0.72, "weekly_demand": 95},
            {"name": "Seasonal candy corn", "annual_margin": 5100, "cv": 0.85, "weekly_demand": 40}
          ],
          "total_category_margin": 146800
        }
      },
      "task": "Classify each item using the ABC/XYZ framework. For each item, recommend the appropriate forecasting method, safety stock service level, review frequency, and replenishment approach.",
      "evaluation_criteria": [
        {
          "criterion": "abc_classification",
          "weight": 0.25,
          "rubric": {
            "pass": "Correctly classifies based on cumulative margin contribution. Items B ($78K, 53%) and A ($42K, 82% cumulative) are A-class. Item D ($18.5K, 94% cumulative) is B-class. Items E ($5.1K, 98%) and C ($3.2K, 100%) are C-class. Uses margin (not revenue or units) as the value metric.",
            "fail": "Classifies based on unit volume rather than margin. Gets the A/B/C boundaries wrong. Classifies more than 3 items as A."
          }
        },
        {
          "criterion": "xyz_classification",
          "weight": 0.25,
          "rubric": {
            "pass": "Correctly classifies based on CV thresholds: Items B (CV 0.28) and A (CV 0.35) are X (CV < 0.5). Item D (CV 0.72) and E (CV 0.85) are Y (CV 0.5–1.0). Item C (CV 1.45) is Z (CV > 1.0). Notes that Item C's low volume and high CV indicate intermittent demand.",
            "fail": "Uses the wrong CV thresholds. Confuses variability with volume. Classifies the high-CV items as X."
          }
        },
        {
          "criterion": "policy_recommendations",
          "weight": 0.35,
          "rubric": {
            "pass": "Assigns differentiated policies: AX items (B, A) get automated replenishment, 95–97.5% service level, weekly review, exponential smoothing or moving average. BY item (D) gets 95% SL, bi-weekly review. CY item (E) gets 90% SL, monthly review, notes seasonal pattern needs attention. CZ item (C) gets 85% SL, monthly review, flags as discontinuation candidate or suggests Croston's method for intermittent demand.",
            "fail": "Applies the same policy to all items. Does not differentiate service levels by segment. Does not flag the CZ item as a special case."
          }
        },
        {
          "criterion": "practical_insights",
          "weight": 0.15,
          "rubric": {
            "pass": "Notes that Item C (imported rice crackers, CZ) should be evaluated for discontinuation given its minimal margin contribution and erratic demand. Notes that Item E's CV was computed on de-seasonalized data so the actual demand pattern may be predictable within its season even though the CV is 0.85.",
            "fail": "Does not recognize the discontinuation question for the CZ item. Does not acknowledge that de-seasonalized CV may overstate unpredictability for genuinely seasonal items."
          }
        }
      ]
    },
    {
      "id": "IDP-003",
      "name": "Selecting the right forecasting method for a trending product",
      "difficulty": "easy",
      "category": "forecasting",
      "context": {
        "situation": "A new plant-based milk brand (Oatly Barista Edition, 32 oz) was added to your assortment 26 weeks ago. It has shown consistent upward trend with the following weekly sales trajectory across your 75-store chain:\n\nWeeks 1–4: avg 180 units/week\nWeeks 5–8: avg 240 units/week\nWeeks 9–13: avg 310 units/week\nWeeks 14–18: avg 380 units/week\nWeeks 19–22: avg 420 units/week\nWeeks 23–26: avg 450 units/week\n\nThere is no obvious seasonal pattern. CV on the de-trended residuals is 0.32. Your current forecasting method for this item is a 4-week simple moving average, which has been consistently under-forecasting by 15–25% (negative bias). The vendor lead time is 10 days.",
        "available_data": {
          "sku": "OATLY-BA-32",
          "product": "Oatly Barista Edition 32 oz",
          "weeks_of_history": 26,
          "trend": "Consistent upward, approximately +15 units/week",
          "seasonal_pattern": "None detected",
          "cv_detrended": 0.32,
          "current_method": "4-week simple moving average",
          "current_bias": "-15 to -25% (systematic under-forecast)",
          "lead_time_days": 10,
          "store_count": 75,
          "recent_weekly_demand": [430, 445, 460, 455]
        }
      },
      "task": "Diagnose why the current method is failing, recommend a replacement forecasting method with specific parameters, and explain how you would transition.",
      "evaluation_criteria": [
        {
          "criterion": "diagnosis",
          "weight": 0.30,
          "rubric": {
            "pass": "Correctly identifies that a simple moving average cannot track a trending demand pattern — it always lags behind by approximately half the window length. The 4-week SMA is centered on 2 weeks ago, so it systematically under-forecasts growing demand. The negative bias of 15–25% is a direct consequence of this lag.",
            "fail": "Does not identify the fundamental mismatch between a moving average and trending demand. Attributes the bias to noise or insufficient history."
          }
        },
        {
          "criterion": "method_recommendation",
          "weight": 0.40,
          "rubric": {
            "pass": "Recommends Holt's double exponential smoothing (or equivalent trend-capturing method). Specifies reasonable parameters: α in the 0.2–0.4 range (to be responsive to the trend) and β in the 0.05–0.15 range (to smooth the trend component). Notes that the product is still in a growth phase and may transition to stabilization, so the method should be reassessed at the 52-week mark. May also suggest a damped trend variant (φ = 0.85–0.95) to prevent overshoot if growth decelerates.",
            "fail": "Recommends continuing with a moving average (just longer window). Recommends Holt-Winters seasonal when no seasonal pattern exists. Recommends a complex ML model when 26 weeks of data is insufficient. Does not specify parameters."
          }
        },
        {
          "criterion": "transition_plan",
          "weight": 0.30,
          "rubric": {
            "pass": "Recommends running the new method in parallel with the current method for 4–8 weeks, comparing WMAPE and bias on each week's forecast. Uses the first 20 weeks of data to fit parameters and weeks 21–26 as a holdout test. Plans to cut over when the new method demonstrates lower WMAPE and reduced bias on the holdout period.",
            "fail": "Suggests switching immediately with no parallel test. Does not mention holdout validation. Proposes an unreasonably long transition period (>12 weeks) for what is a straightforward method change."
          }
        }
      ]
    },
    {
      "id": "IDP-004",
      "name": "Interpreting and acting on a tracking signal alert",
      "difficulty": "easy",
      "category": "forecasting",
      "context": {
        "situation": "Your forecast monitoring system has flagged SKU CP-2201 (craft paper towels, 6-roll pack) with a tracking signal of +5.2. The tracking signal has been climbing for the past 4 weeks: +2.1, +3.0, +3.8, +5.2. The item uses single exponential smoothing with α = 0.15. Weekly demand has been: Forecast 520, Actual 480; Forecast 515, Actual 465; Forecast 510, Actual 450; Forecast 505, Actual 435. The item is classified as BX. There have been no promotional changes, no shelf reset, and no known competitive activity.",
        "available_data": {
          "sku": "CP-2201",
          "product": "Craft paper towels 6-roll pack",
          "abc_xyz": "BX",
          "forecast_method": "Single exponential smoothing, alpha = 0.15",
          "tracking_signal_history": [2.1, 3.0, 3.8, 5.2],
          "recent_forecasts": [520, 515, 510, 505],
          "recent_actuals": [480, 465, 450, 435],
          "cumulative_error": 220,
          "mad": 42.5
        }
      },
      "task": "Interpret what the tracking signal is telling you, diagnose the likely cause, and recommend corrective action.",
      "evaluation_criteria": [
        {
          "criterion": "tracking_signal_interpretation",
          "weight": 0.30,
          "rubric": {
            "pass": "Correctly identifies that a positive tracking signal of +5.2 (exceeding the ±4 threshold) indicates persistent positive bias — the forecast is systematically higher than actuals. The consistent upward trend in the tracking signal over 4 weeks indicates this is not random noise but a structural issue. Notes that the cumulative error (220 units over 4 weeks) divided by MAD (42.5) yields the ~5.2 tracking signal.",
            "fail": "Misinterprets the tracking signal direction (e.g., says demand is exceeding forecast). Does not recognize that +5.2 exceeds the intervention threshold. Dismisses the signal as noise."
          }
        },
        {
          "criterion": "diagnosis",
          "weight": 0.35,
          "rubric": {
            "pass": "Identifies a downward demand level shift: actual demand has dropped from ~520 to ~435 over 4 weeks (a ~16% decline) while the model with α = 0.15 adjusts too slowly. At α = 0.15, the model only incorporates 15% of each error — it will take 10+ more weeks to self-correct. Correctly considers possible causes: competitive product introduction, consumer brand switching, price sensitivity, or distribution loss.",
            "fail": "Does not recognize this as a demand level shift. Attributes the declining demand to normal variability. Does not explain why the low alpha is causing slow adjustment."
          }
        },
        {
          "criterion": "corrective_action",
          "weight": 0.35,
          "rubric": {
            "pass": "Recommends: (1) investigate the root cause before changing the model (check for competitive entry, shelf changes, pricing), (2) temporarily increase α to 0.25–0.30 to allow faster adaptation, or apply a one-time level adjustment to reset the model to the current demand level (~435–450), (3) recalculate safety stock using the updated demand parameters, (4) reduce open POs to avoid building excess at the inflated forecast level.",
            "fail": "Recommends only re-running the model with no parameter change. Recommends switching to a completely different method without diagnosing the cause. Does not mention adjusting POs or safety stock."
          }
        }
      ]
    },
    {
      "id": "IDP-005",
      "name": "Standard safety stock recalculation after lead time increase",
      "difficulty": "easy",
      "category": "safety-stock",
      "context": {
        "situation": "Your vendor for a popular BBQ sauce (Sweet Ray's Original, 18 oz, A-item) has informed you that their lead time is increasing from 7 days to 14 days due to a factory relocation. Average weekly demand is 350 units with a standard deviation of 55 units. Your review period is weekly. Target service level is 95% (Z = 1.65). Current safety stock was calculated at the old 7-day lead time.",
        "available_data": {
          "sku": "SR-1801",
          "product": "Sweet Ray's BBQ Sauce 18 oz",
          "abc_class": "A",
          "weekly_demand_avg": 350,
          "weekly_demand_std": 55,
          "old_lead_time_days": 7,
          "new_lead_time_days": 14,
          "review_period_days": 7,
          "service_level": 0.95,
          "z_score": 1.65,
          "current_on_hand": 950,
          "on_order": 500,
          "on_order_eta_days": 12
        }
      },
      "task": "Calculate the old and new safety stock, the new reorder point, assess the current inventory position against the new parameters, and recommend immediate actions.",
      "evaluation_criteria": [
        {
          "criterion": "safety_stock_comparison",
          "weight": 0.35,
          "rubric": {
            "pass": "Correctly computes old SS = 1.65 × 55 × √(1+1) = 1.65 × 55 × 1.414 ≈ 128 units. New SS = 1.65 × 55 × √(2+1) = 1.65 × 55 × 1.732 ≈ 157 units. Notes the ~23% increase in safety stock from doubling lead time. Calculations within ±10% are acceptable.",
            "fail": "Omits review period. Uses wrong z-score. Gets old SS below 90 or above 170. Gets new SS below 120 or above 210."
          }
        },
        {
          "criterion": "reorder_point_and_position",
          "weight": 0.35,
          "rubric": {
            "pass": "Computes new ROP: demand during (LT + R) + SS = 350/7 × (14+7) + 157 = 50 × 21 + 157 = 1,207 (approx). IP = 950 + 500 = 1,450. IP (1,450) > new ROP (~1,207), so no immediate emergency order is needed, but the buffer is thin — only 243 units above ROP.",
            "fail": "Does not compute inventory position correctly. Uses on-hand alone. Gets ROP below 900 or above 1,500."
          }
        },
        {
          "criterion": "action_recommendations",
          "weight": 0.30,
          "rubric": {
            "pass": "Recommends updating the safety stock parameter in the system, notes that the next regular order should be sized to rebuild to the new target, and flags that the current buffer is thin — if demand spikes or the on-order delivery is late, a stockout is possible. Suggests monitoring this SKU weekly during the transition.",
            "fail": "Takes no action because IP > ROP without noting the thin buffer. Does not mention updating system parameters. Does not consider the delivery risk on the in-transit order."
          }
        }
      ]
    },
    {
      "id": "IDP-006",
      "name": "Seasonal Holt-Winters forecast for sunscreen category with trend",
      "difficulty": "medium",
      "category": "forecasting",
      "context": {
        "situation": "You manage the sunscreen category (12 SKUs, aggregate A-class) for a chain with 90 stores across the Southeast US. Total category weekly demand follows a strong seasonal pattern with a slight upward trend (5–8% YoY growth driven by health awareness). Last year's peak demand was 4,200 units/week in mid-June; the trough was 380 units/week in January. You have 3 full years of weekly history. Your current model is a simple 4-week moving average applied to the total category, which produces large forecast errors during seasonal transitions (spring ramp-up and fall decline). The category buyer needs your 26-week forward forecast to commit pre-season buys with the vendor. Vendor lead time is 8 weeks.",
        "available_data": {
          "category": "Sunscreen",
          "sku_count": 12,
          "abc_class": "A (aggregate)",
          "store_count": 90,
          "history_years": 3,
          "peak_weekly_demand": 4200,
          "trough_weekly_demand": 380,
          "yoy_growth": "5-8%",
          "current_method": "4-week simple moving average",
          "current_wmape": "42% (high due to seasonal transitions)",
          "vendor_lead_time_weeks": 8,
          "current_date": "2025-02-15"
        }
      },
      "task": "Recommend a forecasting approach for this category, explain why the current method fails, specify the model type and parameters, describe how to handle the pre-season buy decision, and identify the key risks.",
      "evaluation_criteria": [
        {
          "criterion": "method_diagnosis_and_selection",
          "weight": 0.30,
          "rubric": {
            "pass": "Correctly identifies that a SMA fails for seasonal demand because it cannot anticipate seasonal ramp-ups or declines — it only reacts after the change has occurred, causing chronic under-forecast during spring and over-forecast during fall. Recommends Holt-Winters multiplicative seasonal (not additive) because the seasonal amplitude grows with the trend (peak is increasing YoY). Specifies 52-week seasonal period.",
            "fail": "Recommends a non-seasonal method. Chooses additive Holt-Winters without justifying the choice or noting the growing amplitude. Does not explain why the SMA fails during transitions."
          }
        },
        {
          "criterion": "parameterization",
          "weight": 0.25,
          "rubric": {
            "pass": "Specifies reasonable parameter ranges: α = 0.1–0.3 (level), β = 0.02–0.10 (trend — kept low to avoid overshoot), γ = 0.1–0.3 (seasonal). Recommends optimizing via cross-validation on the 3-year history with rolling-origin evaluation. Notes that multiplicative seasonal indices should be initialized from the first 2 years and validated on the third year.",
            "fail": "Does not specify parameters or ranges. Uses very high β (>0.2) which would cause trend overshoot. Does not mention cross-validation or holdout testing."
          }
        },
        {
          "criterion": "pre_season_buy_strategy",
          "weight": 0.25,
          "rubric": {
            "pass": "Addresses the 26-week forward forecast for the buyer. Notes that with 8-week vendor lead time, the pre-season buy for peak summer must be committed by early April (8 weeks before mid-June peak). Recommends committing 60–70% of the forecasted season demand in the initial buy and reserving 30–40% for in-season reorders based on early sell-through. Identifies that the 26-week forecast horizon means the model must project through the peak and into the post-peak decline.",
            "fail": "Does not connect the forecast to the buying decision. Ignores the 8-week lead time constraint. Recommends committing 100% of forecasted demand upfront."
          }
        },
        {
          "criterion": "risk_identification",
          "weight": 0.20,
          "rubric": {
            "pass": "Identifies key risks: (1) weather dependency — an unusually cool or rainy summer depresses demand below the seasonal forecast, (2) the trend component may decelerate (5–8% growth may not continue), (3) new competitive products or channel shifts (e.g., Amazon capturing more sunscreen sales) could reduce store-level demand. Recommends monitoring early-season sell-through as the primary risk indicator.",
            "fail": "Does not identify any risks. Lists only generic forecasting risks without connecting to the sunscreen category specifically."
          }
        }
      ]
    },
    {
      "id": "IDP-007",
      "name": "Promotional lift estimation for a product with limited promo history",
      "difficulty": "medium",
      "category": "promotional-planning",
      "context": {
        "situation": "You are planning a 2-week promotion for a premium Greek yogurt (Fage Total 0%, 32 oz, SKU FAGE-32-0) starting in 6 weeks. The promotion is TPR 20% off ($4.79 → $3.83) with a circular feature on page 2. This SKU has only been promoted once before (8 months ago, TPR 15% off only, no circular), which produced a lift of 1.35× baseline. The category (premium yogurt) has been promoted 12 times in the past 2 years across 4 SKUs, with the following lift data:\n\n- TPR only (15–20% off): average lift 1.40× (range 1.25–1.60)\n- TPR + circular: average lift 2.20× (range 1.80–2.80)\n\nBaseline weekly demand for FAGE-32-0 is 280 units. The product has a 21-day shelf life. The vendor requires 3-week order lead time for promotional quantities.",
        "available_data": {
          "sku": "FAGE-32-0",
          "product": "Fage Total 0% Greek Yogurt 32 oz",
          "baseline_weekly": 280,
          "promo_type": "TPR 20% off + circular page 2",
          "promo_duration_weeks": 2,
          "promo_start": "6 weeks from now",
          "own_promo_history": "1 event (TPR 15% off only, lift 1.35x)",
          "category_lift_tpr_only": {"avg": 1.40, "range": [1.25, 1.60]},
          "category_lift_tpr_circular": {"avg": 2.20, "range": [1.80, 2.80]},
          "shelf_life_days": 21,
          "vendor_lead_time_weeks": 3,
          "store_count": 75,
          "current_on_hand": 1200,
          "regular_price": 4.79,
          "promo_price": 3.83
        }
      },
      "task": "Estimate the promotional lift and total demand for the 2-week promotion, plan the inventory requirements including the post-promo dip, and identify the key risks given the perishable nature of the product.",
      "evaluation_criteria": [
        {
          "criterion": "lift_estimation",
          "weight": 0.30,
          "rubric": {
            "pass": "Uses the category-level TPR + circular lift data (avg 2.20×) rather than the own-item TPR-only data (1.35×), because the promotional mechanism is different (circular adds significant lift). May adjust the 2.20× downward slightly because the own-item's only promo at a similar depth produced a below-category-average lift (1.35× vs category TPR avg of 1.40×), suggesting this SKU may be slightly below average in responsiveness. Final lift estimate in the 1.90–2.30× range is expert-level.",
            "fail": "Uses the own-item 1.35× lift directly despite the different promo mechanism. Ignores the category data. Applies the 2.20× without adjusting for the item's apparently lower responsiveness. Estimates a lift below 1.5× or above 3.0×."
          }
        },
        {
          "criterion": "inventory_planning",
          "weight": 0.30,
          "rubric": {
            "pass": "Computes total promo demand: ~2.10× × 280 × 2 weeks ≈ 1,176 units (range 1,008–1,568 based on lift range). Subtracts current on-hand (1,200) and accounts for baseline consumption in the 6 weeks before promo start (280 × 6 = 1,680 baseline). Notes that the 1,200 current units are mostly consumed by baseline demand before the promo starts; need to order promo-specific quantity. PO must be placed within 3 weeks (3-week lead time for delivery before promo start).",
            "fail": "Does not account for baseline demand consuming on-hand before the promo. Computes the PO quantity only for promo demand without considering on-hand depletion. Misses the 3-week lead time ordering deadline."
          }
        },
        {
          "criterion": "post_promo_dip",
          "weight": 0.20,
          "rubric": {
            "pass": "Models the post-promo dip. For a perishable product (21-day shelf life), the forward-buy factor is very low (0.05–0.15) because customers can't stockpile yogurt. Predicts a minimal dip — perhaps 10–20% below baseline for 1 week, then full recovery. Notes that the perishable nature limits pantry loading, which is actually favorable for post-promo planning.",
            "fail": "Applies a large post-promo dip (>30%) appropriate for shelf-stable goods to a perishable product. Ignores the shelf life constraint entirely. Does not model any post-promo period."
          }
        },
        {
          "criterion": "risk_assessment",
          "weight": 0.20,
          "rubric": {
            "pass": "Identifies the spoilage risk: if the lift is at the low end of the range, excess yogurt with 21-day shelf life becomes a waste issue. Recommends ordering conservatively (closer to the low-end lift estimate) and accepting a possible stockout during the promo rather than risking spoilage. Notes that with 3-week lead time, there's no in-promo replenishment option.",
            "fail": "Does not mention spoilage risk for a perishable. Orders for the high-end lift estimate without acknowledging the waste risk. Does not connect the 3-week lead time to the inability to react mid-promotion."
          }
        }
      ]
    },
    {
      "id": "IDP-008",
      "name": "Calculating cannibalization effects for a multi-SKU promotion",
      "difficulty": "medium",
      "category": "promotional-planning",
      "context": {
